('Révolution de 1930', 'revolution-1930-bresil-BR', '1930-10-03', '1930-11-03', 'La Révolution de 1930 porte Getúlio Vargas au pouvoir et met fin à la Première République.', NULL, 8),
('Création de l’Estado Novo', 'creation-estado-novo-bresil-BR', '1937-11-10', '1937-11-10', 'Getúlio Vargas instaure l’Estado Novo, régime autoritaire centralisé.', NULL, 10),
('Participation du Brésil à la Seconde Guerre mondiale', 'participation-seconde-guerre-mondiale-bresil-BR', '1942-08-22', '1945-05-08', 'Le Brésil rejoint les Alliés et envoie la Force expéditionnaire brésilienne combattre en Italie.', NULL, 6),
('Construction de Brasília', 'construction-brasilia-bresil-BR', '1956-01-01', '1960-04-21', 'La nouvelle capitale fédérale est construite au centre du pays et inaugurée en 1960.', NULL, 16),
('Coup d’État militaire de 1964', 'coup-etat-militaire-1964-bresil-BR', '1964-03-31', '1964-04-01', 'Les forces armées renversent le président João Goulart et instaurent une dictature militaire.', NULL, 10),
('Adoption de la Constitution de 1988', 'adoption-constitution-1988-bresil-BR', '1988-10-05', '1988-10-05', 'La Constitution de 1988 rétablit un cadre démocratique et élargit les droits fondamentaux.', NULL, 22),
('Élection directe de Fernando Collor', 'election-fernando-collor-bresil-BR', '1989-12-17', '1989-12-17', 'Fernando Collor de Mello remporte la première élection présidentielle directe depuis la fin du régime militaire.', NULL, 22),
('Plan Real', 'plan-real-bresil-BR', '1994-07-01', '1994-07-01', 'Le Plan Real introduit une nouvelle monnaie et contribue à stabiliser fortement l’économie brésilienne.', NULL, 25),
('Élection de Luiz Inácio Lula da Silva', 'election-lula-da-silva-bresil-BR', '2002-10-27', '2002-10-27', 'Luiz Inácio Lula da Silva est élu président du Brésil.', NULL, 22),
('Organisation des Jeux olympiques de Rio', 'jeux-olympiques-rio-bresil-BR', '2016-08-05', '2016-08-21', 'Rio de Janeiro accueille les Jeux olympiques d’été de 2016.', NULL, 24);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières sociétés agricoles', 'developpement-premieres-societes-agricoles-chili-CL', '0001-01-01', '0500-01-01', 'Développement des premières communautés agricoles et sédentaires sur le territoire correspondant au Chili actuel.', NULL, 17),
('Développement de la culture Chinchorro', 'developpement-culture-chinchorro-chili-CL', '0001-01-01', '1500-01-01', 'La culture Chinchorro se développe dans le nord du Chili et est notamment connue pour ses pratiques funéraires.', NULL, 17),
('Développement des sociétés Diaguita', 'developpement-societes-diaguita-chili-CL', '0800-01-01', '1500-01-01', 'Les sociétés diaguita se développent dans le nord du Chili avec une agriculture et une production artisanale élaborées.', NULL, 17),
('Expansion de l''Empire inca au Chili', 'expansion-empire-inca-chili-CL', '1470-01-01', '1530-01-01', 'Les Incas étendent leur domination vers le sud jusqu''à une partie du territoire chilien.', NULL, 12),
('Arrivée de Diego de Almagro', 'arrivee-diego-almagro-chili-CL', '1535-01-01', '1537-01-01', 'Diego de Almagro mène une expédition espagnole vers les territoires correspondant au Chili actuel.', NULL, 18),
('Arrivée de Pedro de Valdivia', 'arrivee-pedro-de-valdivia-chili-CL', '1540-01-01', '1541-01-01', 'Pedro de Valdivia entreprend la conquête espagnole durable du territoire chilien.', NULL, 12),
('Fondation de Santiago', 'fondation-santiago-chili-CL', '1541-02-12', '1541-02-12', 'Pedro de Valdivia fonde Santiago de la Nueva Extremadura, future capitale du Chili.', NULL, 16),
('Début de la guerre d''Arauco', 'guerre-arauco-chili-CL', '1550-01-01', '1656-01-01', 'Un long conflit oppose les Espagnols aux populations mapuches dans le sud du Chili.', NULL, 6),
('Fondation de Concepción', 'fondation-concepcion-chili-CL', '1550-10-05', '1550-10-05', 'Pedro de Valdivia fonde Concepción, qui devient un important centre colonial du sud du Chili.', NULL, 16),
('Destruction de plusieurs villes espagnoles par les Mapuches', 'destruction-villes-espagnoles-mapuches-chili-CL', '1598-01-01', '1604-01-01', 'Une grande offensive mapuche entraîne la destruction ou l''abandon de plusieurs établissements espagnols au sud du fleuve Biobío.', NULL, 9),
('Établissement de la frontière du Biobío', 'etablissement-frontiere-biobio-chili-CL', '1641-01-01', '1641-01-01', 'Le parlement de Quillín contribue à établir le fleuve Biobío comme frontière entre les territoires espagnols et mapuches.', NULL, 14),
('Création de la Capitainerie générale du Chili', 'creation-capitainerie-generale-chili-CL', '1778-01-01', '1778-01-01', 'Les réformes bourboniennes renforcent l''organisation administrative et militaire du Chili colonial.', NULL, 17),
('Première Junte nationale de gouvernement', 'premiere-junte-nationale-gouvernement-chili-CL', '1810-09-18', '1810-09-18', 'Une junte de gouvernement est formée à Santiago, marquant le début du processus d''indépendance chilien.', NULL, 22),
('Victoire de Chacabuco', 'bataille-chacabuco-chili-CL', '1817-02-12', '1817-02-12', 'Les forces indépendantistes dirigées notamment par José de San Martín et Bernardo O''Higgins remportent la bataille de Chacabuco.', NULL, 7),
('Déclaration d''indépendance du Chili', 'declaration-independance-chili-CL', '1818-02-12', '1818-02-12', 'Le Chili proclame officiellement son indépendance vis-à-vis de l''Espagne.', NULL, 11),
('Victoire de Maipú', 'bataille-maipu-chili-CL', '1818-04-05', '1818-04-05', 'La victoire des indépendantistes à Maipú consolide l''indépendance du Chili.', NULL, 7),
('Guerre du Pacifique', 'guerre-pacifique-chili-CL', '1879-02-14', '1884-04-04', 'Le Chili affronte la Bolivie et le Pérou dans un conflit portant notamment sur les territoires riches en ressources du désert d''Atacama.', NULL, 6),
('Guerre civile chilienne', 'guerre-civile-chilienne-CL', '1891-01-16', '1891-09-01', 'Un conflit oppose les forces favorables au président José Manuel Balmaceda au Congrès chilien.', NULL, 6),
('Coup d''État de 1973', 'coup-etat-1973-chili-CL', '1973-09-11', '1973-09-11', 'Les forces armées renversent le président Salvador Allende et instaurent une dictature militaire dirigée par Augusto Pinochet.', NULL, 10),
('Retour à la démocratie', 'retour-democratie-chili-CL', '1990-03-11', '1990-03-11', 'L''entrée en fonction de Patricio Aylwin marque le retour à un gouvernement démocratiquement élu après la dictature militaire.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières sociétés agricoles', 'developpement-premieres-societes-agricoles-colombie-CO', '0001-01-01', '0500-01-01', 'Développement des premières communautés agricoles sédentaires sur le territoire correspondant à la Colombie actuelle.', NULL, 17),
('Développement de la culture San Agustín', 'developpement-culture-san-agustin-colombie-CO', '0100-01-01', '0800-01-01', 'La culture de San Agustín se développe dans les Andes méridionales et produit d''importants ensembles de sculptures monumentales.', NULL, 17),
('Développement de la culture Tumaco-La Tolita', 'developpement-culture-tumaco-la-tolita-colombie-CO', '0300-01-01', '0600-01-01', 'La culture Tumaco-La Tolita se développe sur la côte pacifique avec une importante tradition métallurgique.', NULL, 17),
('Développement de la culture Muisca', 'developpement-culture-muisca-colombie-CO', '0800-01-01', '1537-01-01', 'Les Muiscas établissent une société organisée dans les hautes terres de la cordillère Orientale.', NULL, 17),
('Développement des réseaux commerciaux précolombiens', 'developpement-reseaux-commerciaux-precolombiens-colombie-CO', '0800-01-01', '1500-01-01', 'Des réseaux d''échanges relient les différentes sociétés autochtones des Andes et des régions côtières.', NULL, 25),
('Arrivée de Rodrigo de Bastidas', 'arrivee-rodrigo-de-bastidas-colombie-CO', '1501-01-01', '1501-01-01', 'Rodrigo de Bastidas explore une partie de la côte caraïbe du territoire colombien.', NULL, 18),
('Arrivée de Gonzalo Jiménez de Quesada', 'arrivee-gonzalo-jimenez-quesada-colombie-CO', '1536-01-01', '1537-01-01', 'Gonzalo Jiménez de Quesada mène une expédition espagnole vers les hautes terres occupées par les Muiscas.', NULL, 12),
