('Fondation de Bogotá', 'fondation-bogota-colombie-CO', '1538-08-06', '1538-08-06', 'Gonzalo Jiménez de Quesada fonde Santa Fe de Bogotá dans les hauts plateaux andins.', NULL, 16),
('Création de l''audience royale de Santa Fe', 'creation-audience-royale-santa-fe-colombie-CO', '1549-01-01', '1549-01-01', 'Une audience royale est créée à Santa Fe afin d''administrer la Nouvelle-Grenade.', NULL, 17),
('Création de la vice-royauté de Nouvelle-Grenade', 'creation-vice-royaute-nouvelle-grenade-colombie-CO', '1717-01-01', '1717-01-01', 'La monarchie espagnole crée la vice-royauté de Nouvelle-Grenade, dont le siège est à Bogotá.', NULL, 17),
('Révolte des Comuneros', 'revolte-comuneros-colombie-CO', '1781-03-16', '1781-10-01', 'La révolte des Comuneros constitue un important soulèvement contre les réformes fiscales espagnoles.', NULL, 9),
('Indépendance de la Nouvelle-Grenade', 'independance-nouvelle-grenade-colombie-CO', '1810-07-20', '1810-07-20', 'Le soulèvement de Bogotá ouvre le processus d''indépendance de la Nouvelle-Grenade.', NULL, 11),
('Bataille de Boyacá', 'bataille-boyaca-colombie-CO', '1819-08-07', '1819-08-07', 'La victoire des forces indépendantistes à Boyacá joue un rôle décisif dans la libération de la Nouvelle-Grenade.', NULL, 7),
('Création de la Grande Colombie', 'creation-grande-colombie-colombie-CO', '1819-12-17', '1819-12-17', 'Le Congrès d''Angostura établit la République de Colombie, connue historiquement sous le nom de Grande Colombie.', NULL, 17),
('Dissolution de la Grande Colombie', 'dissolution-grande-colombie-colombie-CO', '1831-01-01', '1831-01-01', 'La Grande Colombie se désagrège et la Nouvelle-Grenade devient un État indépendant.', NULL, 22),
('Adoption de la Constitution de 1886', 'adoption-constitution-1886-colombie-CO', '1886-08-05', '1886-08-05', 'Une nouvelle constitution centralise l''État et fonde la République de Colombie moderne.', NULL, 22),
('Guerre des Mille Jours', 'guerre-mille-jours-colombie-CO', '1899-10-17', '1902-11-21', 'Une guerre civile oppose les libéraux et les conservateurs dans une grande partie du pays.', NULL, 6),
('Séparation du Panama', 'separation-panama-colombie-CO', '1903-11-03', '1903-11-03', 'Le Panama se sépare de la Colombie et devient un État indépendant.', NULL, 11),
('Adoption de la Constitution de 1991', 'adoption-constitution-1991-colombie-CO', '1991-07-04', '1991-07-04', 'Une nouvelle constitution transforme les institutions colombiennes et renforce les droits fondamentaux.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières sociétés agricoles', 'developpement-premieres-societes-agricoles-equateur-EC', '0001-01-01', '0500-01-01', 'Développement des premières communautés agricoles sédentaires sur le territoire correspondant à l’Équateur actuel.', NULL, 17),
('Développement de la culture Valdivia', 'developpement-culture-valdivia-equateur-EC', '0150-01-01', '0350-01-01', 'La culture Valdivia développe des communautés agricoles et une importante production céramique sur la côte équatorienne.', NULL, 17),
('Développement de la culture Chorrera', 'developpement-culture-chorrera-equateur-EC', '0300-01-01', '0950-01-01', 'La culture Chorrera se développe sur la côte et dans les régions intérieures de l’Équateur précolombien.', NULL, 17),
('Développement de la culture Jama-Coaque', 'developpement-culture-jama-coaque-equateur-EC', '0500-01-01', '1532-01-01', 'La culture Jama-Coaque se développe sur la côte nord de l’Équateur avec une riche tradition artistique et commerciale.', NULL, 17),
('Développement des sociétés Cañari', 'developpement-societes-canari-equateur-EC', '0500-01-01', '1532-01-01', 'Les Cañaris développent des sociétés organisées dans les Andes méridionales de l’Équateur.', NULL, 17),
('Conquête inca du territoire équatorien', 'conquete-inca-territoire-equatorien-equateur-EC', '1460-01-01', '1532-01-01', 'Les Incas étendent progressivement leur empire vers le nord et intègrent une grande partie de l’Équateur actuel.', NULL, 12),
('Arrivée de Francisco Pizarro', 'arrivee-francisco-pizarro-equateur-EC', '1532-01-01', '1532-01-01', 'Les expéditions espagnoles atteignent le territoire équatorien dans le contexte de la conquête de l’Empire inca.', NULL, 13),
('Conquête espagnole de Quito', 'conquete-espagnole-quito-equateur-EC', '1534-01-01', '1534-01-01', 'Les forces espagnoles prennent le contrôle de Quito après la chute de l’Empire inca.', NULL, 12),
('Fondation espagnole de Quito', 'fondation-espagnole-quito-equateur-EC', '1534-12-06', '1534-12-06', 'Sebastián de Belalcázar établit la ville espagnole de San Francisco de Quito.', NULL, 16),
('Création de la Real Audiencia de Quito', 'creation-real-audiencia-quito-equateur-EC', '1563-01-01', '1563-01-01', 'La Couronne espagnole crée la Real Audiencia de Quito pour administrer une partie des territoires du nord-ouest de l’Amérique du Sud.', NULL, 17),
('Révolte des Alcabalas', 'revolte-alcabalas-equateur-EC', '1592-01-01', '1593-01-01', 'Les habitants de Quito se soulèvent contre l’imposition de nouvelles taxes par les autorités coloniales espagnoles.', NULL, 9),
('Révolte de Quito', 'revolte-quito-1765-equateur-EC', '1765-05-22', '1765-06-01', 'Une importante révolte populaire éclate à Quito contre les réformes fiscales et le monopole sur l’alcool.', NULL, 9),
('Première Junte autonome de Quito', 'premiere-junte-autonome-quito-equateur-EC', '1809-08-10', '1809-08-10', 'Une junte autonome est formée à Quito, marquant une étape importante du processus d’émancipation de l’Équateur.', NULL, 22),
('Massacre du 2 août 1810 à Quito', 'massacre-2-aout-1810-quito-equateur-EC', '1810-08-02', '1810-08-02', 'Une insurrection à Quito est réprimée par les forces royalistes, provoquant de nombreuses victimes.', NULL, 9),
('Bataille de Pichincha', 'bataille-pichincha-equateur-EC', '1822-05-24', '1822-05-24', 'Les forces indépendantistes commandées par Antonio José de Sucre remportent une victoire décisive près de Quito.', NULL, 7),
('Indépendance de Quito', 'independance-quito-equateur-EC', '1822-05-24', '1822-05-24', 'La victoire de Pichincha permet la libération de Quito et son intégration au nouvel État indépendant.', NULL, 11),
('Création de la République de l’Équateur', 'creation-republique-equateur-equateur-EC', '1830-05-13', '1830-05-13', 'L’Équateur se sépare de la Grande Colombie et devient une république indépendante.', NULL, 11),
('Révolution libérale équatorienne', 'revolution-liberale-equateur-EC', '1895-06-05', '1895-06-05', 'La révolution libérale menée par Eloy Alfaro transforme profondément les institutions et la société équatoriennes.', NULL, 8),
('Guerre des Quatre Jours', 'guerre-quatre-jours-equateur-EC', '1932-08-28', '1932-09-01', 'Une crise politique et militaire éclate à Quito après les élections présidentielles contestées de 1932.', NULL, 6),
('Adoption de la Constitution de 2008', 'adoption-constitution-2008-equateur-EC', '2008-09-28', '2008-09-28', 'Un référendum approuve une nouvelle constitution qui réorganise profondément les institutions de l’Équateur.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières sociétés autochtones', 'developpement-premieres-societes-autochtones-guyana-GY', '0001-01-01', '0500-01-01', 'Développement des premières communautés autochtones sur le territoire correspondant à la Guyana actuelle.', NULL, 17),
('Développement des sociétés arawaks', 'developpement-societes-arawaks-guyana-GY', '0500-01-01', '1500-01-01', 'Les populations arawaks développent des communautés agricoles et des réseaux d''échanges dans la région.', NULL, 17),
('Développement des sociétés caribes', 'developpement-societes-caribes-guyana-GY', '0800-01-01', '1500-01-01', 'Les populations caribes s''implantent et développent leurs propres réseaux sociaux et commerciaux.', NULL, 17),
('Développement des échanges interrégionaux', 'developpement-echanges-interregionaux-guyana-GY', '1000-01-01', '1500-01-01', 'Les sociétés autochtones développent des échanges reliant la côte atlantique à l''intérieur des Guyanes.', NULL, 25),
('Arrivée des premiers explorateurs européens', 'arrivee-premiers-explorateurs-europeens-guyana-GY', '1499-01-01', '1499-01-01', 'Des explorateurs espagnols atteignent les côtes de la région des Guyanes.', NULL, 18),
('Premières explorations néerlandaises', 'premieres-explorations-neerlandaises-guyana-GY', '1580-01-01', '1596-01-01', 'Les Néerlandais commencent à explorer et à cartographier les côtes de la Guyana actuelle.', NULL, 18),
